package com.ams.modules.passwordreset.controller;
import java.io.IOException;import com.ams.common.util.JsonUtil;import com.ams.modules.passwordreset.repository.impl.PasswordResetRepositoryImpl;import com.ams.modules.passwordreset.service.PasswordResetService;import com.ams.modules.passwordreset.service.impl.PasswordResetServiceImpl;import com.ams.modules.user.repository.impl.UserRepositoryImpl;import jakarta.servlet.ServletException;import jakarta.servlet.annotation.WebServlet;import jakarta.servlet.http.*;
@WebServlet("/api/v1/auth/password/*") public class PasswordResetController extends HttpServlet{
 private static final long serialVersionUID=1L;private PasswordResetService service;@Override public void init()throws ServletException{service=new PasswordResetServiceImpl(new PasswordResetRepositoryImpl(),new UserRepositoryImpl());}
 @Override protected void doPost(HttpServletRequest req,HttpServletResponse resp)throws IOException{try{String p=req.getPathInfo();if("/forgot".equals(p)){String token=service.requestReset(req.getParameter("email"));resp.setStatus(200);resp.getWriter().write("{\"status\":\"SUCCESS\",\"message\":\"If the account exists, a reset process has been started.\",\"resetToken\":"+JsonUtil.toJson(token)+"}");return;}if("/reset".equals(p)){service.resetPassword(req.getParameter("token"),req.getParameter("newPassword"));resp.setStatus(200);resp.getWriter().write(JsonUtil.response("SUCCESS","Password reset successful"));return;}resp.setStatus(404);resp.getWriter().write(JsonUtil.response("ERROR","Endpoint not found"));}catch(Exception e){resp.setStatus(400);resp.setContentType("application/json");resp.getWriter().write(JsonUtil.response("ERROR",e.getMessage()));}}
}
